import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;
import org.springframework.mock.web.MockServletContext;

import jakarta.servlet.ServletException;

@ResourceLock(Resources.SYSTEM_PROPERTIES)
class WorkbenchDeletionStartupTest {

	private String previous;

	@BeforeEach
	void saveProperty() {
		previous = System.getProperty(RepositoryDeletionPolicy.PASSWORD_PROPERTY);
	}

	@AfterEach
	void restoreProperty() {
		if (previous == null) {
			System.clearProperty(RepositoryDeletionPolicy.PASSWORD_PROPERTY);
		} else {
			System.setProperty(RepositoryDeletionPolicy.PASSWORD_PROPERTY, previous);
		}
	}

	@Test
	void anEmptyPasswordFailsApplicationStartupEvenForARemoteDefaultServer() {
		System.setProperty(RepositoryDeletionPolicy.PASSWORD_PROPERTY, "");
		WorkbenchGateway gateway = new WorkbenchGateway();
		try {
			assertThatThrownBy(() -> gateway.init(TestServletConfig.withParams("gateway", "default-server",
					"https://example.org/rdf4j-server")))
							.isInstanceOf(ServletException.class)
							.hasMessageContaining("deletion password");
		} finally {
			gateway.destroy();
		}
	}

	@Test
	void malformedVerifierFailsApplicationStartupWithoutExposingConfiguration() {
		String verifier = "{pbkdf2-sha256}600000:private-invalid-salt:private-invalid-hash";
		System.setProperty(RepositoryDeletionPolicy.PASSWORD_PROPERTY, verifier);
		WorkbenchGateway gateway = new WorkbenchGateway();
		try {
			assertThatThrownBy(() -> gateway.init(TestServletConfig.withParams("gateway", "default-server",
					"https://example.org/rdf4j-server")))
							.isInstanceOf(ServletException.class)
							.hasMessageContaining("deletion password")
							.satisfies(failure -> {
								StringWriter trace = new StringWriter();
								failure.printStackTrace(new PrintWriter(trace));
								assertThat(trace.toString()).doesNotContain(verifier, "private-invalid-salt",
										"private-invalid-hash");
							});
		} finally {
			gateway.destroy();
		}
	}

	@Test
	void aLazyLocalDeleteServletUsesTheApplicationStartupSnapshot() throws Exception {
		System.setProperty(RepositoryDeletionPolicy.PASSWORD_PROPERTY, "startup password");
		MockServletContext context = new MockServletContext();
		WorkbenchGateway gateway = new WorkbenchGateway();
		gateway.init(new TestServletConfig("gateway", context,
				Map.of("default-server", "https://example.org/rdf4j-server")));
		System.clearProperty(RepositoryDeletionPolicy.PASSWORD_PROPERTY);
		RepositoryManager manager = mock(RepositoryManager.class);
		DeleteServlet servlet = new DeleteServlet();
		servlet.setRepositoryManager(manager);
		try {
			servlet.init(new TestServletConfig("delete", context, Map.of("cookie-max-age", "300")));
			MockHttpServletRequest request = new MockHttpServletRequest("POST", "/delete");
			request.addParameter("id", "memory");
			MockHttpServletResponse response = new MockHttpServletResponse();
			servlet.service(request, response);
			assertThat(response.getStatus()).isEqualTo(403);
			verify(manager, never()).removeRepository("memory");
			request.addParameter("delete-password", "startup password");
			response = new MockHttpServletResponse();
			servlet.service(request, response);
			assertThat(response.getRedirectedUrl()).isEqualTo("../");
			verify(manager).removeRepository("memory");
		} finally {
			servlet.destroy();
			gateway.destroy();
		}
	}
}
